10,"before":{"id":10,"name":"Orc","uuid":"2005895293702434","rarity":"COMMON","version":"1.0","trait_id":1461,"meta_data":{"source":{"url":"https://2e.aonprd.com/Ancestries.aspx?ID=66","book":"Player Core","page":"70"}},"created_at":"2023-12-14T04:42:25.284011+00:00","deprecated":null,"operations":[{"id":"2ab7d55b-60a2-4051-9307-e4c73a6d6596","data":{"value":10,"variable":"MAX_HEALTH_ANCESTRY"},"type":"setValue"},{"id":"09cbf36d-44d6-436d-9456-5499516314aa","data":{"value":"medium","variable":"SIZE"},"type":"setValue"},{"id":"72506287-ce22-4033-866d-ab849ac4ec9e","data":{"value":25,"variable":"SPEED"},"type":"setValue"},{"id":"2406087d-787e-4a0d-9807-e167794d3471","data":{"languageId":81},"type":"giveLanguage"},{"id":"d6dea13c-9849-4988-910b-786afad7f468","data":{"languageId":89},"type":"giveLanguage"},{"id":"e423312d-baab-4e75-91ec-11599102f395","data":{"value":"[\n  \"Goblin\",\n  \"Jotun\",\n  \"Petran\",\n  \"Sakvroth\"\n]","variable":"CORE_LANGUAGES"},"type":"setValue"},{"id":"013967a1-ba53-4692-a13a-ceae609481af","data":{"type":"sense","abilityBlockId":20769},"type":"giveAbilityBlock"},{"id":"eabb4cd7-5aad-4f7c-a712-95d5e272bcf3","data":{"title":"Select an Attribute","modeType":"FILTERED","optionType":"ADJ_VALUE","optionsFilters":{"id":"8c1e7659-5029-4d00-8d77-f10f50b4688d","type":"ADJ_VALUE","group":"ATTRIBUTE","value":{"value":1}},"optionsPredefined":[]},"type":"select"},{"id":"d3f89920-a79a-4f46-b32a-0c88b543ccec","data":{"traitId":2399},"type":"giveTrait"},{"id":"da9c1890-53ff-4033-8396-da52153bd63c","data":{"title":"Select an Attribute","modeType":"FILTERED","optionType":"ADJ_VALUE","optionsFilters":{"id":"51fb1543-8428-4ad5-bc53-40b5b2225a48","type":"ADJ_VALUE","group":"ATTRIBUTE","value":{"value":1}},"optionsPredefined":[]},"type":"select"}],"artwork_url":"https://images.demiplane.com/elements/pathfinder-2e/ancestries/ancestry-orc-rm-detail.png?format=webp&quality=90&width=1920","description":"> _Orcs are proud, strong people with hardened physiques who value physical might and glory in combat._\n\nOrcs are forged in the fires of violence and conflict, often from the moment they are born. As they live lives that are frequently cut brutally short, orcs revel in testing their strength against worthy foes, often by challenging a higher-ranking member of their community for dominance. Orcs often struggle to gain acceptance among other communities, who frequently see them as brutes. Those who earn the loyalty of an orc friend, however, soon learn that an orc's fidelity and honesty are unparalleled. Orc culture teaches that they are shaped by the challenges they survive, and the most worthy survive the most hardships. Orcs who attain both a long life and great triumphs command immense respect.\n\nIf you want a character who is hardy, fearsome, and excels at feats of physical prowess, you should play an orc.","content_source_id":1},"after":{"id":10,"name":"Orc","uuid":"2671137626513187","rarity":"COMMON","version":"1.0","trait_id":1461,"meta_data":{"source":{"url":"https://2e.aonprd.com/Ancestries.aspx?ID=66","book":"Player Core","page":"70"}},"created_at":"2023-12-14T04:42:25.284011+00:00","deprecated":null,"operations":[{"id":"2ab7d55b-60a2-4051-9307-e4c73a6d6596","data":{"value":10,"variable":"MAX_HEALTH_ANCESTRY"},"type":"setValue"},{"id":"09cbf36d-44d6-436d-9456-5499516314aa","data":{"value":"medium","variable":"SIZE"},"type":"setValue"},{"id":"72506287-ce22-4033-866d-ab849ac4ec9e","data":{"value":25,"variable":"SPEED"},"type":"setValue"},{"id":"2406087d-787e-4a0d-9807-e167794d3471","data":{"languageId":81},"type":"giveLanguage"},{"id":"d6dea13c-9849-4988-910b-786afad7f468","data":{"languageId":89},"type":"giveLanguage"},{"id":"e423312d-baab-4e75-91ec-11599102f395","data":{"value":"[\n  \"Goblin\",\n  \"Jotun\",\n  \"Petran\",\n  \"Sakvroth\"\n]","variable":"CORE_LANGUAGES"},"type":"setValue"},{"id":"013967a1-ba53-4692-a13a-ceae609481af","data":{"type":"sense","abilityBlockId":20769},"type":"giveAbilityBlock"},{"id":"eabb4cd7-5aad-4f7c-a712-95d5e272bcf3","data":{"title":"Select an Attribute","modeType":"FILTERED","optionType":"ADJ_VALUE","optionsFilters":{"id":"8c1e7659-5029-4d00-8d77-f10f50b4688d","type":"ADJ_VALUE","group":"ATTRIBUTE","value":{"value":1}},"optionsPredefined":[]},"type":"select"},{"id":"d3f89920-a79a-4f46-b32a-0c88b543ccec","data":{"traitId":2399},"type":"giveTrait"},{"id":"da9c1890-53ff-4033-8396-da52153bd63c","data":{"title":"Select an Attribute","modeType":"FILTERED","optionType":"ADJ_VALUE","optionsFilters":{"id":"51fb1543-8428-4ad5-bc53-40b5b2225a48","type":"ADJ_VALUE","group":"ATTRIBUTE","value":{"value":1}},"optionsPredefined":[]},"type":"select"}],"artwork_url":"https://images.demiplane.com/elements/pathfinder-2e/ancestries/ancestry-orc-rm-detail.png?format=webp&quality=90&width=1920","description":"> _Orcs are proud, strong people with hardened physiques who value physical might and glory in combat._\n\nOrcs are forged in the fires of violence and conflict, often from the moment they are born. As they live lives that are frequently cut brutally short, orcs revel in testing their strength against worthy foes, often by challenging a higher-ranking member of their community for dominance. Orcs often struggle to gain acceptance among other communities, who frequently see them as brutes. Those who earn the loyalty of an orc friend, however, soon learn that an orc's fidelity and honesty are unparalleled. Orc culture teaches that they are shaped by the challenges they survive, and the most worthy survive the most hardships. Orcs who attain both a long life and great triumphs command immense respect.\n\nIf you want a character who is hardy, fearsome, and excels at feats of physical prowess, you should play an orc.","content_source_id":3}},{"table":"trait","id":1348,"before":{"id":1348,"name":"Elf","uuid":"4613985024096727","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=588","book":"Player Core","page":"455"},"ancestry_trait":true},"create