_trait":true},"created_at":"2023-12-14T04:35:20.548618+00:00","description":"This indicates content from the dwarf ancestry.","content_source_id":1},"after":{"id":1467,"name":"Dwarf","uuid":"7840415119350289","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=584","book":"Player Core","page":"455"},"ancestry_trait":true},"created_at":"2023-12-14T04:35:20.548618+00:00","description":"This indicates content from the dwarf ancestry.","content_source_id":3}},{"table":"trait","id":1468,"before":{"id":1468,"name":"Goblin","uuid":"8937305273372612","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=618","book":"Player Core","page":"456"},"ancestry_trait":true},"created_at":"2023-12-14T04:41:19.653122+00:00","description":"This indicates content from the goblin ancestry.","content_source_id":1},"after":{"id":1468,"name":"Goblin","uuid":"3244209636824582","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=618","book":"Player Core","page":"456"},"ancestry_trait":true},"created_at":"2023-12-14T04:41:19.653122+00:00","description":"This indicates content from the goblin ancestry.","content_source_id":3}},{"table":"trait","id":1474,"before":{"id":1474,"name":"Halfling","uuid":"1814241673844771","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=621","book":"Player Core","page":"457"},"ancestry_trait":true},"created_at":"2023-12-14T04:41:36.398774+00:00","description":"This indicates content from the halfling ancestry.","content_source_id":1},"after":{"id":1474,"name":"Halfling","uuid":"4590047798938818","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=621","book":"Player Core","page":"457"},"ancestry_trait":true},"created_at":"2023-12-14T04:41:36.398774+00:00","description":"This indicates content from the halfling ancestry.","content_source_id":3}}],"rival_academies":{"id":493,"url":"https://paizo.com/products/btq05yck","keys":null,"name":"Rival Academies","group":"lost-omens","user_id":null,"meta_data":{"counts":{"feat":78,"spell":43,"creature":1,"class_archetype":2}},"created_at":"2025-02-25T23:49:27.247566+00:00","deprecated":null,"foundry_id":null,"operations":[],"artwork_url":"","description":"The finest mages, scientists, and academics of the Age of Lost Omens are gathering!  \nJourney to a fortress-city in demon-ravaged Sarkoris to learn the ancient magical secrets of the Magaambya's wizards, Lepidstadt's bleeding-edge theories on reanimating flesh with electricity, the extraplanar fey philosophies of the Cobyslarni, and the lore of more than a dozen other academies! With so many prominent scholars in one place, rivalries are sure to abound—whether in the classroom, on the sports fields, or during field trips to dangerous lands.  \nThis 128-page book gives GMs and players a vibrant roster of luminaries, students, athletes, and wizards to build their very own magical academies. Whether players build bonds with classmates or clash with rivals, they'll gain diverse options like advanced spymaster gear, dazzling new martial arts techniques, or new wizard spells and schools, including the remastered Runelord!  \nWritten by: Sharang Biswas, Jeremy Blum, Carlos Cisco, Aoife Ester, Laura Lynn Horst, Andrew Mullen, Kendra Leigh Speedling, Stephanie Lundeen, Mahpiya, Collette Quach, Mikhail Rekun, Erin Roberts, Navaar Seik-Jackson, Shahreena Shahrani, Gina Susanna, Tan Shao Han, Esther Wallace, and Landon Winkler.","require_key":false,"contact_info":null,"is_published":true,"required_content_sources":[1,256,13,842]}}$shared104$::jsonb as spec),
global_shared_actual as materialized(
 select p as expected,(to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) as row from global_shared_settings g cross join lateral jsonb_array_elements(g.spec->'patches') p left join public.ancestry r on r.id=(p->>'id')::bigint where p->>'table'='ancestry'
 union all
 select p as expected,(to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) as row from global_shared_settings g cross join lateral jsonb_array_elements(g.spec->'patches') p left join public.trait r on r.id=(p->>'id')::bigint where p->>'table'='trait'
),
global_shared_state as materialized(select coalesce(count(*)=12 and bool_and((row=expected->'before') is true),false) as before,coalesce(count(*)=12 and bool_and((row=expected->'after') is true),false) as after from global_shared_actual),
global_shared_guard as materialized(select ((s.before or s.after)
 and not exists(select 1 from public.content_update u cross join global_shared_settings g cross join lateral jsonb_array_elements(g.spec->'patches') p
  where upper(btrim(coalesce(u.status->>'state','PENDING'))) not in('APPROVED','REJECTED') and u.type=p->>'table' and (u.ref_id=(p->>'id')::bigint or u.data->>'id'=p->>'id'
